INSERT INTO `his_config_info` VALUES (0, 168, 'learn-shop-core-file.yml', 'DEFAULT_GROUP', 'learn-shop-admin-system', 'start: true\nspring:\n  cloud:\n    bus:\n      trace:\n        enabled: true #开启消息跟踪\n  activiti:\n    check-process-definitions: false #校验流程文件，默认校验resources下的processes文件夹里的流程文件\n    mail-server-use-ssl: true\n    database-schema-update: false #首次启动时，需要设置为true，自动建表\n    async-executor-activate: false\n  thymeleaf:\n    mode: HTML5\n    cache: false\n    prefix: classpath:/templates/\n  freemarker:\n    cache: false\n    template-loader-path: classpath:/templates/\n\n\ncustom:\n  menu:\n    write-cache: true #菜单写入缓存中\n  common:\n    base-file-path: D:/uploadfile # base 路径\n    image-mapping: /displayImag # 映射处理的路径，当 url 中有 /displayImag 时，资源映射到 D:/temp-rainy/\n    markdown-img-path: /markdown # 图片保存的路径\n    user-icon-img-path: /usericon # 图片保存的路径\n    start-init-data: true #启动时，是否初始数据（首次启动时需要设置为true,默认为true）\n  mail:\n    from: NULL #系统对外发送邮件的地址\n    host: smtp.exmail.qq.com\n    port: 465\n    username: XXXXXX\n    password: XXXXXX\n  thread-pool:\n    core-pool-size: 8 # 线程池长期维持的线程数 默认 8\n    maximum-pool-size: 10 # 线程数的上限 默认 10\n    capacity: 512 # 任务的排队队列 默认 512\nmybatis-plus:\n  configuration:\n    cache-enabled: false\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath*:mapper/**/*Mapper.xml', '56c271e869946e5a4ce9a0fddcba69e9', '2025-09-16 21:07:13', '2025-09-16 21:07:13', 'nacos', '172.29.0.1', 'I', 'dev', '', 'formal', '', '{\"src_user\":\"nacos\",\"type\":\"yaml\"}');
INSERT INTO `his_config_info` VALUES (483, 169, 'learn-shop-core-file.yml', 'DEFAULT_GROUP', 'learn-shop-admin-system', 'start: true\nspring:\n  cloud:\n    bus:\n      trace:\n        enabled: true #开启消息跟踪\n  activiti:\n    check-process-definitions: false #校验流程文件，默认校验resources下的processes文件夹里的流程文件\n    mail-server-use-ssl: true\n    database-schema-update: false #首次启动时，需要设置为true，自动建表\n    async-executor-activate: false\n  thymeleaf:\n    mode: HTML5\n    cache: false\n    prefix: classpath:/templates/\n  freemarker:\n    cache: false\n    template-loader-path: classpath:/templates/\n\n\ncustom:\n  menu:\n    write-cache: true #菜单写入缓存中\n  common:\n    base-file-path: D:/uploadfile # base 路径\n    image-mapping: /displayImag # 映射处理的路径，当 url 中有 /displayImag 时，资源映射到 D:/temp-rainy/\n    markdown-img-path: /markdown # 图片保存的路径\n    user-icon-img-path: /usericon # 图片保存的路径\n    start-init-data: true #启动时，是否初始数据（首次启动时需要设置为true,默认为true）\n  mail:\n    from: NULL #系统对外发送邮件的地址\n    host: smtp.exmail.qq.com\n    port: 465\n    username: XXXXXX\n    password: XXXXXX\n  thread-pool:\n    core-pool-size: 8 # 线程池长期维持的线程数 默认 8\n    maximum-pool-size: 10 # 线程数的上限 默认 10\n    capacity: 512 # 任务的排队队列 默认 512\nmybatis-plus:\n  configuration:\n    cache-enabled: false\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath*:mapper/**/*Mapper.xml', '56c271e869946e5a4ce9a0fddcba69e9', '2025-09-16 21:08:01', '2025-09-16 21:08:01', 'nacos', '172.29.0.1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (358, 170, 'sys-config-db.yml', 'DEFAULT_GROUP', 'common', 'db.service.ipAddress: 127.0.0.1\n####################################################################################################\n############################################ 主从分离 sharding-jdbc hikari 数据源配置 ################\n####################################################################################################\nspring:\n  datasource:\n    url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n    username: root\n    password: root\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    hikari:\n      pool-name: MyHikariCP\n      minimum-idle: 5\n      maximum-pool-size: 20\n      connection-timeout: 30000\n      max-lifetime: 1800000\n      idle-timeout: 600000\n      connection-test-query: SELECT 1\n# spring:\n  # shardingsphere:\n  #   datasource:\n  #     names: master,slave1,slave2\n  #     master: # 主数据源\n  #       type: com.zaxxer.hikari.HikariDataSource\n  #       driver-class: com.mysql.cj.jdbc.Driver\n  #       jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n  #       username: root\n  #       password: root\n  #     slave1: # 从数据源\n  #       type: com.zaxxer.hikari.HikariDataSource\n  #       driver-class: com.mysql.cj.jdbc.Driver\n  #       jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n  #       username: root\n  #       password: root\n  #     slave2: # 从数据源\n  #       type: com.zaxxer.hikari.HikariDataSource\n  #       driver-class: com.mysql.cj.jdbc.Driver\n  #       jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n  #       username: root\n  #       password: root\n  #   masterslave:\n  #     load-balance-algorithm-type: round_robin\n  #     name: dataSource\n  #     master-data-source-name: master\n  #     slave-data-source-names: slave1,slave2\n  #   props:\n  #     sql-show: true # 显示SQL', '4d9a1d44b63e0fa99dff8fe19cec2a0a', '2025-09-28 19:13:29', '2025-09-28 19:13:30', 'nacos', '172.29.0.1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (358, 171, 'sys-config-db.yml', 'DEFAULT_GROUP', 'common', 'db.service.ipAddress: 127.0.0.1\n####################################################################################################\n############################################ 主从分离 sharding-jdbc hikari 数据源配置 ################\n####################################################################################################\n# spring:\n#   datasource:\n#     url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n#     username: root\n#     password: root\n#     driver-class-name: com.mysql.cj.jdbc.Driver\n#     hikari:\n#       pool-name: MyHikariCP\n#       minimum-idle: 5\n#       maximum-pool-size: 20\n#       connection-timeout: 30000\n#       max-lifetime: 1800000\n#       idle-timeout: 600000\n#       connection-test-query: SELECT 1\n# spring:\nshardingsphere:\n  datasource:\n    names: master,slave1,slave2\n    master: # 主数据源\n      type: com.zaxxer.hikari.HikariDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n    slave1: # 从数据源\n      type: com.zaxxer.hikari.HikariDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n    slave2: # 从数据源\n      type: com.zaxxer.hikari.HikariDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n\nrules:\n  - !SINGLE\n    tables:\n      - \"*.*\"\n\n  - !READWRITE_SPLITTING\n    dataSourceGroups:\n      readwrite_ds:\n        writeDataSourceName: master\n        readDataSourceNames:\n          - slave1\n          - slave2\n        transactionalReadQueryStrategy: PRIMARY\n        loadBalancerName: random\n    loadBalancers:\n      random:\n        type: RANDOM\n\nprops:\n  sql-show: true\n  check-table: false\n  default-data-source-name: master', '8b2a3a7159c8eb5664ed050ca1e3aeba', '2025-09-28 19:31:16', '2025-09-28 19:31:16', 'nacos', '172.29.0.1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (358, 172, 'sys-config-db.yml', 'DEFAULT_GROUP', 'common', 'db.service.ipAddress: 127.0.0.1\n####################################################################################################\n############################################ 主从分离 sharding-jdbc hikari 数据源配置 ################\n####################################################################################################\n# spring:\n#   datasource:\n#     url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n#     username: root\n#     password: root\n#     driver-class-name: com.mysql.cj.jdbc.Driver\n#     hikari:\n#       pool-name: MyHikariCP\n#       minimum-idle: 5\n#       maximum-pool-size: 20\n#       connection-timeout: 30000\n#       max-lifetime: 1800000\n#       idle-timeout: 600000\n#       connection-test-query: SELECT 1\n# spring:\nshardingsphere:\n  datasource:\n    names: master,slave1,slave2\n    master: # 主数据源\n      type: com.alibaba.druid.pool.DruidDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n    slave1: # 从数据源\n      type: com.alibaba.druid.pool.DruidDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n    slave2: # 从数据源\n      type: com.alibaba.druid.pool.DruidDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n\nrules:\n  - !SINGLE\n    tables:\n      - \"*.*\"\n\n  - !READWRITE_SPLITTING\n    dataSourceGroups:\n      readwrite_ds:\n        writeDataSourceName: master\n        readDataSourceNames:\n          - slave1\n          - slave2\n        transactionalReadQueryStrategy: PRIMARY\n        loadBalancerName: random\n    loadBalancers:\n      random:\n        type: RANDOM\n\nprops:\n  sql-show: true\n  check-table: false\n  default-data-source-name: master', '24ffcee0be2ed3585d61317e23ae1a6d', '2025-09-28 19:34:44', '2025-09-28 19:34:44', 'nacos', '172.29.0.1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (358, 173, 'sys-config-db.yml', 'DEFAULT_GROUP', 'common', 'db.service.ipAddress: 127.0.0.1\n####################################################################################################\n############################################ 主从分离 sharding-jdbc hikari 数据源配置 ################\n####################################################################################################\n# spring:\n#   datasource:\n#     url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n#     username: root\n#     password: root\n#     driver-class-name: com.mysql.cj.jdbc.Driver\n#     hikari:\n#       pool-name: MyHikariCP\n#       minimum-idle: 5\n#       maximum-pool-size: 20\n#       connection-timeout: 30000\n#       max-lifetime: 1800000\n#       idle-timeout: 600000\n#       connection-test-query: SELECT 1\n# spring:\nshardingsphere:\n  datasource:\n    names: master,slave1,slave2\n    master: # 主数据源\n      testWhileIdle: false\n      type: com.alibaba.druid.pool.DruidDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n    slave1: # 从数据源\n      testWhileIdle: false\n      type: com.alibaba.druid.pool.DruidDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n    slave2: # 从数据源\n      testWhileIdle: false\n      type: com.alibaba.druid.pool.DruidDataSource\n      driver-class: com.mysql.cj.jdbc.Driver\n      jdbc-url: jdbc:mysql://${db.service.ipAddress}:3306/learn?useUnicode=true&characterEncoding=utf8&useSSL=false&autoReconnect=true&serverTimezone=Asia/Shanghai\n      username: root\n      password: root\n\nrules:\n  - !SINGLE\n    tables:\n      - \"*.*\"\n\n  - !READWRITE_SPLITTING\n    dataSourceGroups:\n      readwrite_ds:\n        writeDataSourceName: master\n        readDataSourceNames:\n          - slave1\n          - slave2\n        transactionalReadQueryStrategy: PRIMARY\n        loadBalancerName: random\n    loadBalancers:\n      random:\n        type: RANDOM\n\nprops:\n  sql-show: true\n  check-table: false\n  default-data-source-name: master', '858b72f64f48ec0e017431737cf34bc9', '2025-09-28 19:36:18', '2025-09-28 19:36:18', 'nacos', '172.29.0.1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
