Shanghai\n    username: root\n    password: root\n\nrules:\n  - !SINGLE\n    tables:\n      - \"*.*\"\n\n  - !READWRITE_SPLITTING\n    dataSourceGroups:\n      readwrite_ds:\n        writeDataSourceName: master\n        readDataSourceNames:\n          - slave1\n          - slave2\n        transactionalReadQueryStrategy: PRIMARY\n        loadBalancerName: random\n    loadBalancers:\n      random:\n        type: RANDOM\n\nprops:\n  sql-show: true\n  check-table: false\n  default-data-source-name: master', 'ba49e16dd0483f4e2ad7b1b7baa75aa6', '2025-09-28 19:37:04', '2025-09-28 19:37:04', 'nacos', '172.29.0.1', 'U', 'dev', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
